sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // gs.info('WRM Sync BR fired for reservation: ' + current.number);

    // Ensure workspace reference exists
    if (!current.workspace) {
        // gs.info('WRM Sync: No workspace reference found, exiting.');
        return;
    }

    // Get the workspace record
    var workspace = new GlideRecord('x_1534869_wrm_workspace_options');
    if (!workspace.get(current.workspace)) {
        // gs.info('WRM Sync: Workspace record not found for sys_id: ' + current.workspace);
        return;
    }

    // Determine new workspace status based on reservation status
    var newStatus = '';

    switch (current.reservation_status.toString()) {
        case 'pending_check_in':
        case 'checked_in':
            newStatus = 'unavailable';
            break;

        case 'checked_out':
        case 'no_show':
        case 'cancelled':
            newStatus = 'available';
            break;

        default:
            // No action for other statuses
            // gs.info('WRM Sync: Status not mapped, exiting. Status was: ' + current.reservation_status);
            return;
    }

    // Only update if the workspace status is actually changing
    if (workspace.status != newStatus) {
        gs.info('WRM Sync: Updating workspace ' + workspace.number + ' to status: ' + newStatus);
		workspace.setWorkflow(false);
        workspace.status = newStatus;		
        workspace.update();
    } else {
        // gs.info('WRM Sync: Workspace already set to ' + newStatus + ', no update needed.');
    }

})(current, previous);
